## ---- teaching-assoc
assoc <- function(key, pairs) {
  if (is.null(pairs)) {
    FALSE
  } else if (equal(key, head(head(pairs))) ) {
    head(pairs)  # a key-value pair
  } else {
    assoc(key, tail(pairs))
  }
}

equal <- function(xs, ys) {
  if (is_pair(xs)) {
    is_pair(ys) &&
      equal(head(xs), head(ys)) &&
      equal(tail(xs), tail(ys))
  } else {
    identical(xs, ys)
  }
}
